import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"無妄","description":"周易正义 - 無妄","frontmatter":{"title":"無妄","description":"周易正义 - 無妄"},"headers":[],"relativePath":"zh/classics/zhengyi/025.md","filePath":"zh/classics/zhengyi/025.md"}'),l={name:"zh/classics/zhengyi/025.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>天雷无妄</p></blockquote><blockquote><p>卦辞：元亨利贞。其匪正有眚，不利有攸往。</p></blockquote><blockquote><p>彖曰：无妄，刚自外来而为主于内，动而健，刚中而应。大亨以正，天之命也。“其匪正有眚，不利有攸往”，无妄之往何之矣？天命不祐，行矣哉！</p></blockquote><h1 id="無妄" tabindex="-1">無妄 <a class="header-anchor" href="#無妄" aria-label="Permalink to “無妄”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：无妄者，以刚为内主，动而能健，以此临下，物皆无敢诈伪虚妄，俱行实理，所以大得亨通，利於贞正，故曰“元亨利贞”也。“其匪正有眚不利有攸往”者，物既无妄，当以正道行之。若其匪依正道，则有眚灾，不利有所往也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="无妄-刚自外来而为主於内。-​" tabindex="-1">无妄，刚自外来而为主於内。 ​ <a class="header-anchor" href="#无妄-刚自外来而为主於内。-​" aria-label="Permalink to “无妄，刚自外来而为主於内。 ​”">​</a></h3><p>王弼：谓震也。</p><h3 id="动而健-​" tabindex="-1">动而健， ​ <a class="header-anchor" href="#动而健-​" aria-label="Permalink to “动而健， ​”">​</a></h3><p>王弼：震动而乾健也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：以此卦象释能致无妄之义。以震之刚从外而来，为主於内，震动而乾健，故能使物“无妄”也。</p><h3 id="刚中而应。-​" tabindex="-1">刚中而应。 ​ <a class="header-anchor" href="#刚中而应。-​" aria-label="Permalink to “刚中而应。 ​”">​</a></h3><p>王弼：谓五也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：明爻义能致无妄。九五以刚处中，六二应之，是“刚中而应”。刚中则能制断虚实，有应则物所顺从，不敢虚妄也。</p><h3 id="大亨以正-天之命也。-​" tabindex="-1">大亨以正，天之命也。 ​ <a class="header-anchor" href="#大亨以正-天之命也。-​" aria-label="Permalink to “大亨以正，天之命也。 ​”">​</a></h3><p>王弼：刚自外来，而为主於内，动而愈健。“刚中而应”，威刚方正，私欲不行，何可以妄？使有妄之道灭，无妄之道成，非大亨利贞而何？刚自外来，而为主於内，则柔邪之道消矣。动而愈健，则刚直之道通矣。“刚中而应”，则齐明之德著矣。故“大亨以正”也。天之教命，何可犯乎？何可妄乎？是以匪正则有眚，而“不利有攸往”也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>“大亨以正，天之命也”。○正义曰：释“元亨利贞”之义。威刚方正，私欲不行，何可以妄？此天之教命也。天道纯阳，刚而能健，是乾德相似，故云“天之命”也。既是天命，岂可犯乎？○注“刚自外来”至“不利有攸往”也。○正义曰：云“使有妄之道灭，无妄之道成”者，妄，谓虚妄矫诈，不循正理。若无刚中之主，柔弱邪僻，则物皆诈妄，是有妄之道兴也。今遇刚中之主，威严刚正，在下畏威，不敢诈妄，是有妄之道灭，无妄之道成。</p><h3 id="其匪正有眚-不利有攸往-。无妄之往-何之矣-天命不祐-行矣哉-​" tabindex="-1">“其匪正有眚，不利有攸往”。无妄之往，何之矣？天命不祐，行矣哉！ ​ <a class="header-anchor" href="#其匪正有眚-不利有攸往-。无妄之往-何之矣-天命不祐-行矣哉-​" aria-label="Permalink to ““其匪正有眚，不利有攸往”。无妄之往，何之矣？天命不祐，行矣哉！ ​”">​</a></h3><p>王弼：匪正有眚，不求改以从正，而欲有所往，居不可以妄之时，而欲以不正有所往，将欲何之天命之所不祐，竟矣哉！</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>“其匪正有眚”至“天命不祐行矣哉”。○正义曰：“其匪正有眚，不利有攸往，无妄之往何之矣”者，此释“匪正有眚不利有攸往”之义也。“无妄之往何之矣”，上“之”是语辞，下“之”是適也。身既非正，在“无妄”之世，欲有所往，何所之適矣？故云“无妄之往何之矣”。“天命不祐行矣哉”者，身既非正，欲有所往，犯违天命，则天命不祐助也。必竟行矣哉！言终竟行此不祐之事也。○注“匪正有眚”至“不祐竟矣哉”。○正义曰：“竟矣哉”者，竟谓终竟，言天所不祐，终竟行矣哉！</p><h2 id="《象》曰-天下雷行-物与无妄。-​" tabindex="-1">《象》曰：天下雷行，物与无妄。 ​ <a class="header-anchor" href="#《象》曰-天下雷行-物与无妄。-​" aria-label="Permalink to “《象》曰：天下雷行，物与无妄。 ​”">​</a></h2><p>王弼：与，辞也，犹皆也。天下雷行，物皆不可以妄也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“天下雷行”者，雷是威恐之声。今天下雷行，震动万物，物皆惊肃，无敢虚妄，故云“天下雷行”，物皆“无妄”也。</p><h3 id="先王以茂对时育万物。-​" tabindex="-1">先王以茂对时育万物。 ​ <a class="header-anchor" href="#先王以茂对时育万物。-​" aria-label="Permalink to “先王以茂对时育万物。 ​”">​</a></h3><p>王弼：茂，盛也。物皆不敢妄，然后万物乃得各全其性，对时育物，莫盛於斯也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：茂，盛也。对，当也。言先王以此无妄盛事，当其无妄之时，育养万物也。此唯王者其德乃耳，非诸侯已下所能，故不云君子，而言“先王”也。案：诸卦之《象》，直言两象，即以卦名结之，若“雷在地中，复”。今《无妄》应云：“天下雷行，无妄。”今云“物与无妄”者，欲见万物皆无妄，故加“物与”二字也。其馀诸卦，未必万物皆与卦名同义，故直显象，以卦结之。至如复卦，唯阳气复，非是万物皆复。举复一卦，馀可知矣。</p><h2 id="初九-无妄往-吉。-​" tabindex="-1">初九：无妄往，吉。 ​ <a class="header-anchor" href="#初九-无妄往-吉。-​" aria-label="Permalink to “初九：无妄往，吉。 ​”">​</a></h2><p>王弼：体刚处下，以贵下贱，行不犯妄，故往得其志。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：体刚居下，以贵下贱，所行教化，不为妄动，故“往吉”而得志也。</p><h3 id="《象》曰-无妄-之往-得志也。-​" tabindex="-1">《象》曰：“无妄”之往，得志也。 ​ <a class="header-anchor" href="#《象》曰-无妄-之往-得志也。-​" aria-label="Permalink to “《象》曰：“无妄”之往，得志也。 ​”">​</a></h3><h2 id="六二-不耕获-不菑畬-则利有攸往。-​" tabindex="-1">六二：不耕获，不菑畬，则利有攸往。 ​ <a class="header-anchor" href="#六二-不耕获-不菑畬-则利有攸往。-​" aria-label="Permalink to “六二：不耕获，不菑畬，则利有攸往。 ​”">​</a></h2><p>王弼：不耕而获，不菑而畬，代终已成而不造也。不擅其美，乃尽臣道，故“利有攸往”。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“利有攸往”。○正义曰：“不耕获不菑畬”者，六二处中得位，尽於臣道，不敢创首，唯守其终，犹若田农不敢发首而耕，唯在后获刈而已。不敢菑发新田，唯治其菑熟之地，皆是不为其始而成其末，犹若为臣之道，不为事始而代君有终也。则“利有攸往”者，为臣如此，则利有攸往，若不如此，则往而无利也。</p><h3 id="《象》曰-不耕获-未富也。-​" tabindex="-1">《象》曰：“不耕获”，未富也。 ​ <a class="header-anchor" href="#《象》曰-不耕获-未富也。-​" aria-label="Permalink to “《象》曰：“不耕获”，未富也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“不耕而获”之义。不敢前耕，但守后获者，未敢以耕耕之与获，俱为己事。唯为后获，不敢先耕事。既阙初，不擅其美，故云“未富也”。</p><h2 id="六三-无妄之灾-或系之牛。行人之得-邑人之灾。-​" tabindex="-1">六三：无妄之灾，或系之牛。行人之得，邑人之灾。 ​ <a class="header-anchor" href="#六三-无妄之灾-或系之牛。行人之得-邑人之灾。-​" aria-label="Permalink to “六三：无妄之灾，或系之牛。行人之得，邑人之灾。 ​”">​</a></h2><p>王弼：以阴居阳，行违谦顺，是“无妄”之所以为灾也。牛者稼穑之资也。二以不耕而获，“利有攸往”，而三为不顺之行，故“或系之牛”，是有司之所以为获，彼人之所以为灾也，故曰“行人之得，邑人之灾”也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>“六三”至“人之灾”。○正义曰：“无妄”之世，邪道不行。六三阴居阳位，失其正道，行违谦顺而乖臣范，故“无妄”之所以为灾矣。牛者稼穑之资。六三僣为耕事，行唱始之道，而为不顺王事之行，故有司或系其牛，制之使不妄造，故曰“或系之牛”也。“行人”者，有司之义也。有司系得其牛，是“行人”制之得功，故曰“行人之得”。彼居三者，是处邑之人僣为耕事，受其灾罚，故曰：“行人之得，邑人之灾”也。</p><h3 id="《象》曰-行人-得牛-邑人-灾也。-​" tabindex="-1">《象》曰：“行人”得牛，“邑人”灾也。 ​ <a class="header-anchor" href="#《象》曰-行人-得牛-邑人-灾也。-​" aria-label="Permalink to “《象》曰：“行人”得牛，“邑人”灾也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“行人之得”义也。以行人所得，谓得牛也。此则得牛，彼则为灾，故云“邑人灾”也。</p><h2 id="九四-可贞-无咎。-​" tabindex="-1">九四：可贞，无咎。 ​ <a class="header-anchor" href="#九四-可贞-无咎。-​" aria-label="Permalink to “九四：可贞，无咎。 ​”">​</a></h2><p>王弼：处“无妄”之时，以阳居阴，以刚乘柔，履於谦顺，比近至尊，故可以任正，固有所守而“无咎”也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：以阳居阴，以刚乘柔，履於谦顺，上近至尊，可以任正，固有所守而无咎，故曰“可贞无咎”也。</p><h3 id="《象》曰-可贞-无咎-固有之也。-​" tabindex="-1">《象》曰：“可贞，无咎”，固有之也。 ​ <a class="header-anchor" href="#《象》曰-可贞-无咎-固有之也。-​" aria-label="Permalink to “《象》曰：“可贞，无咎”，固有之也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“可贞无咎”之义。所以可执贞正，言坚固有所执守，故曰“无咎”也。</p><h2 id="九五-无妄之疾-勿药有喜。-​" tabindex="-1">九五：无妄之疾，勿药有喜。 ​ <a class="header-anchor" href="#九五-无妄之疾-勿药有喜。-​" aria-label="Permalink to “九五：无妄之疾，勿药有喜。 ​”">​</a></h2><p>王弼：居得尊位，为无妄之主者也。下皆“无妄”，害非所致而取药焉，疾之甚也。非妄之灾，勿治自复，非妄而药之则凶，故曰“勿药有喜”。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“无妄之疾”者，凡祸疾所起，由有妄而来。今九五居得尊位，为无妄之主，下皆“无妄”，而偶然有此疾害，故云“无妄之疾”也。“勿药有喜”者，若疾自己招，或寒暑饮食所致，当须治疗。若其自然之疾，非己所致，疾当自损，勿须药疗而“有喜”也。此假病象以喻人事，犹若人主而刚正自修，身无虚妄，下亦无虚妄，而遇逢凶祸，若尧、汤之厄，灾非己招，但顺时修德，勿须治理，必欲除去，不劳烦天下，是“有喜”也。然尧遭洪水，使鲧、禹治之者，虽知灾未可息，必须顺民之心。鲧之不成，以灾未息也。禹能治救，灾欲尽也，是亦自然之灾，“勿药有喜”之义也。</p><h3 id="《象》曰-无妄之药-不可试也。-​" tabindex="-1">《象》曰：无妄之药，不可试也。 ​ <a class="header-anchor" href="#《象》曰-无妄之药-不可试也。-​" aria-label="Permalink to “《象》曰：无妄之药，不可试也。 ​”">​</a></h3><p>王弼：药攻有妄者也，而反攻“无妄”，故不可试也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：解“勿药有喜”之义。若有妄致疾，其药可用。若身既“无妄”，自然致疾，其药不可试也。若其试之，恐更益疾也。言非妄有灾不可治也，若必欲治之，则劳烦於下，害更甚也。此非直施於人主，至於凡人之事，亦皆然也。若己之无罪，忽逢祸患，此乃自然之理，不须忧劳救护，亦恐反伤其性。</p><h2 id="上九-无妄行-有眚-无攸利。-​" tabindex="-1">上九：无妄行，有眚，无攸利。 ​ <a class="header-anchor" href="#上九-无妄行-有眚-无攸利。-​" aria-label="Permalink to “上九：无妄行，有眚，无攸利。 ​”">​</a></h2><p>王弼：处不可妄之极，唯宜静保其身而已，故不可以行也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：处不可妄之极，唯宜静保其身。若动行，必有灾眚，无所利也。位处穷极，动则致灾。故《象》云：“无妄之行，穷之灾也。”</p><h3 id="《象》曰-无妄-之行-穷之灾也。-​" tabindex="-1">《象》曰：“无妄”之行，穷之灾也。 ​ <a class="header-anchor" href="#《象》曰-无妄-之行-穷之灾也。-​" aria-label="Permalink to “《象》曰：“无妄”之行，穷之灾也。 ​”">​</a></h3>',72)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
